import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int[][] m = new int[rows][cols];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) m[r][c] = sc.nextInt();
        int total = 0;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) total += m[r][c];
        System.out.println("total=" + total);
        System.out.print("rowsums=");
        for (int r = 0; r < rows; r++) {
            int rowSum = 0;
            for (int c = 0; c < cols; c++) rowSum += m[r][c];
            System.out.print(rowSum + " ");
        }
        System.out.println();
        int[] colSum = new int[cols];
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) colSum[c] += m[r][c];
        System.out.print("colsums=");
        for (int c = 0; c < cols; c++) System.out.print(colSum[c] + " ");
        System.out.println();
        int best = m[0][0];
        int bestR = 0;
        int bestC = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (m[r][c] > best) { best = m[r][c]; bestR = r; bestC = c; }
            }
        }
        System.out.println("max=" + best + " " + bestR + " " + bestC);
        if (rows == cols) {
            int diag = 0;
            for (int i = 0; i < rows; i++) diag += m[i][i];
            System.out.println("diag=" + diag);
        } else {
            System.out.println("diag=none");
        }
    }
}

