import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();
        int k = sc.nextInt();
        int[] rev = Arrays.copyOf(a, n);
        int i = 0;
        int j = n - 1;
        while (i < j) {
            int t = rev[i]; rev[i] = rev[j]; rev[j] = t;
            i++;
            j--;
        }
        System.out.println("reversed=" + Arrays.toString(rev));
        int[] rot = new int[n];
        for (int p = 0; p < n; p++) rot[p] = a[(p + k) % n];
        System.out.println("rotated=" + Arrays.toString(rot));
        int[] freq = new int[10];
        for (int p = 0; p < n; p++) freq[a[p]]++;
        System.out.print("freq=");
        for (int v = 0; v < 10; v++) System.out.print(freq[v] + " ");
        System.out.println();
        int mode = 0;
        for (int v = 1; v < 10; v++) {
            if (freq[v] > freq[mode]) mode = v;
        }
        System.out.println("mode=" + mode);
    }
}

