import java.util.*;

public class Main {
    static int countGreater(int[] a, int threshold) {
        int count = 0;
        for (int i = 0; i < a.length; i++) {
            if (a[i] > threshold) count++;
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();
        int t = sc.nextInt();
        System.out.println(countGreater(a, t));
