import java.util.*;

public class Main {
    static int sum(int[] a) {
        int total = 0;
        for (int x : a) total += x;
        return total;
    }

    static int max(int[] a) {
        int best = a[0];
        for (int i = 1; i < a.length; i++) {
            if (a[i] > best) best = a[i];
        }
        return best;
    }

    static int countGreater(int[] a, int k) {
        int count = 0;
        for (int x : a) {
            if (x > k) count++;
        }
        return count;
    }

    static int[] reversed(int[] a) {
        int[] out = new int[a.length];
        for (int i = 0; i < a.length; i++) out[i] = a[a.length - 1 - i];
        return out;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();
        int k = sc.nextInt();
        System.out.println("sum=" + sum(a));
        System.out.println("max=" + max(a));
        System.out.println("count=" + countGreater(a, k));
        System.out.println("reversed=" + Arrays.toString(reversed(a)));
